 andrew:{n:"Andreas (Andrew) H. Hatlem",st:"doc",line:"hatlem",par:["hanss","petrine"],role:"Great-great-uncle (Harald's uncle)",b:"25 Dec 1874, Hyllestad",d:"16 Jan 1962, Washington County, Minnesota",sp:[],ev:[["1875","Listed as a son of Hans Hanssen and Petrine at Varlien",["c1875h"]],["1891","At home at Hatlem with his parents and sisters",["c1891hh"]],["1898","Registered in Bergen on 26 August to emigrate, as an unmarried farmer's son from Varlien, Hyllestad, travelling on the American Line",["em1898"]],["1898","Probably the Andreas H Hatlem who arrived in Philadelphia on the Waesland on 11 September, last residence Hyllestad, heading for Marinette, Wisconsin. The sailing date fits his Bergen registration. FamilySearch's Philadelphia passenger index cards also list an Andreas H Hatlem, b. 1875, immigration 1898",["fh","pha98"]],["1917–18","Steamfitter in Minneapolis (First World War draft registration)",["fh"]],["1930","Minneapolis, working for the telephone company, with his wife Annie and daughter Florence",["fh"]],["1922","Daughter Florence born on 26 May in Minneapolis. Her Social Security record names her parents as Andrew H. Hatlem and Annie C. Christianson",["sbn"]],["1946","His wife Annie (née Christianson) died on 8 October in Hennepin County",["fh","sbn"]],["1962","Died 16 January in Washington County, Minnesota. The Minnesota death index and the Social Security file give his birth date as 25 Dec 1874, in Norway",["fh","sbn"]]],note:"His place in the family is documented in the 1875 and 1891 censuses and his 1898 emigration. The later US records come from a Nasjonalarkivet forum thread and are probable matches."},
 annemarie:{n:"Anne Marie Hatlem (Marie Hornbeck)",st:"doc",line:"hatlem",par:["hanss","petrine"],role:"Great-great-aunt (Harald's aunt)",b:"18 Feb 1884, Hyllestad",d:"June 1974, South San Francisco, California",ev:[["1891","Anna Marie, aged 7, at home at Hatlem with her parents",["c1891hh"]],["1900","Servant in her brother Hans's household at Ytre Hatlem",["c1900h"]],["1907","Registered in Bergen on 12 April to emigrate to Waunakee, Wisconsin, with the Allan Line. A seamstress living in Bergen, she paid her own way",["em1907"]],["1910","Probably the 'Mary Hatlem' working as a servant in Minneapolis",["fh"]],["c. 1910","Married Harry Myron Hornbeck (b. 1875, Pennsylvania)",["fh2"]],["1914","Son Van H. Hornbeck born on 9 July in Alameda County, California. His mother's maiden name is recorded as Hatlem",["fh2"]],["1920","Marie Hornbeck, in Oakland with her husband and children. Her immigration year is given as 1907",["fh2"]],["1930","San Francisco, with her husband Harry and their children",["fh2"]],["1974","Died in June; last residence South San Francisco. The Social Security index gives her birth date as 18 Feb 1884",["fh2"]]],note:"Her Norwegian records are documented. The American identification, as Marie Hornbeck, rests on records quoted on the Nasjonalarkivet forum: the matching birth date, her immigration year and her maiden name in her children's birth records. It was accepted there by her family."},
