 hansGS:{n:"Hans Gerhard Hansen Smilden",st:"doc",line:"hatlem",par:["hansJen","halfri"],role:"2nd great-granduncle (great-grandmother Ingeborg's brother) · emigrant to North Dakota",b:"16 Nov 1873, Smilden, Hyllestad",d:"7 Dec 1928, North Dakota",ev:[["1873","Born 16 November and baptised 23 November",["b1873hg"]],["1875","At home at Smilden",["c1875s"]],["1891","Living at home at Smilden with his parents Hans Jensen and Halfri and his sister Ingeborg",["c1891sm"]],["1893","Emigrated from Bergen on 24 May on the Allan Line, aged 19, with two other Hyllestad men",["em1893hg"]],["1896","According to the county history he first worked in Minnesota lumber camps, then came to Larimore in 1896 and homesteaded in Section 2 of Moraine township, Grand Forks County, North Dakota",["nhs"]],["1897","Married Maren Totland (b. Feb 1879 in Norway; arrived 1895)",["nhs"]],["1893","According to his naturalisation papers he arrived in New York in June 1893",["nhs"]],["1918","His WWI draft registration gives his birth date as November 1873",["nhs"]],["1900","US census: Hans H. Smilden, farmer, Moraine township, Grand Forks Co., N.D., immigrated 1893, with his wife Maren and their children Gustie and Hans",["nhs"]],["1904","US land patent of 1 August for his homestead (Township 151 N, Range 56 W, Section 2)",["nhs"]],["1910","US census: Hans H. 'Smelden', Larimore, naturalised citizen, with Maren and seven children",["nhs"]],["1912","His brother-in-law Hans Hatlem and nephew Hjalmar came to him in Larimore: Hans's September 1912 border card names his destination as brother-in-law Hans H. Smelden, Larimore, N.D.",["card12"]],["1920","US census: farmer in Hegton township, Grand Forks Co., with Maren and eight children at home",["nhs"]],["1928","Died 7 December",["nhs"]]],note:"Identified as the Norwegian Hans Gerhard by his birth (Nov 1873), his 1893 emigration and his use of the Smilden name; the Smilden descendants in America reached the same conclusion. His wife Maren died on 6 November 1946, according to her death certificate. Their children, all born in North Dakota, were Gustie, Hans, Hannah, Thomas, Inga, Tina, Henry, Ingvold, Joseph and Marie. Only those confirmed as deceased are shown here. The US details come from a published forum transcription of the census, not from images I have seen."},
 tenaS:{n:"Tena Larsena Hatten (née Smilden)",st:"doc",line:"hatlem",par:["hansGS"],role:"First cousin of grandfather Harald",b:"24 Oct 1906, Moraine township, Grand Forks Co., North Dakota",d:"20 Feb 1999, Larimore, North Dakota",ev:[["1906","Born 24 October, daughter of Hans and Maren (Totland) Smilden",["obtena"]],["1914","Moved with her family to Larimore",["obtena"]],["1954","Married Eugene Hatten on 4 December in Sterling, Illinois, where she ran a boarding house and worked at Northwestern Steel and Wire",["obtena"]],["1999","Died 20 February in Larimore; buried in Bellevue Cemetery, Larimore",["obtena"]]]},
 madsS:{n:"Mads Hansen Smilden",st:"doc",line:"hatlem",par:["hansJen","halfri"],role:"2nd great-granduncle (great-grandmother Ingeborg's brother)",b:"22 Feb 1865, Smilden, Hyllestad",ev:[["1865","At home at Smilden, an infant",["c1865s"]],["1875","At home at Smilden",["c1875s"]],["1890","Married Martha Hatvig of Os on 1 November in Johannes parish, Bergen; a journeyman shoemaker. His father is Hans Jensen Smilden",["m1890m"]],["1910","Shoemaker master at Nygaardsgate 42, Bergen, with his wife Martha and eight children: Anna (b. 1892), Harald Andreas (1894), Hjalmar Martin (1896), Therese (1898), Artur (1900), Milly (1904), Edith (1906) and Solveig (1907)",["c1910m"]],["1920","Shoemaker with his own shoe shop on Nygårdsgaten, Bergen",["c1920ms"]],["1922","Still at Nygaardsgate 42 with Martha and four of the children",["c1922m"]]],note:"A note in the Norway Heritage thread says he emigrated in 1890, but the Bergen records show he married and stayed in Bergen as a shoemaker."},
 hansJH:{n:"Hans Jensen (Hatlem)",st:"prob",line:"hatlem",par:[],role:"3rd great-grandfather (probable, through both Halfri and Hans sen.)",d:"before 1865",ev:[["1831","Married Trine Clausdatter in Lavik on 13 July; his father is Jens Johannesen (parish register as transcribed by researchers)",["nhs"]],["1836","Father of Halfri, born at Hatlem on 17 April (baptism as transcribed by researchers)",["nhs"]]],note:"Researchers in the Norway Heritage thread list the children of Hans Jensen and Trine Clausdatter at Hatlem: Hans (b. 1833, probably died young), Halfri (1836), Hans (b. 16 Oct 1838), Johanne (1840) and Mari (1842). Halfri is our 2nd great-grandmother, Ingeborg's mother. The Hans born at Hatlem in 1838 is very probably Hans Hanssen Hatlem sen. (b. 1838 at Hatlem), whose parents we had not found. If so, Hans Hatlem jr. and his wife Ingeborg were first cousins. This is marked Probable because I have not seen the original 1838 baptism myself."},
 trineK:{n:"Trine (Thrine) Clausdatter",st:"doc",line:"hatlem",par:["clausH","johanneR"],role:"3rd great-grandmother",b:"14 Mar 1812 (baptised), Indrebø, Bø (Lavik)",d:"1 Mar 1905, Hatlem, Hyllestad (buried 10 Mar)",ev:[["1831","Married Hans Jensen in Lavik on 13 July (as transcribed by researchers)",["nhs"]],["1865","Remarried; wife of Anthonius Berentsen at Indre Hatlem, with children from her first marriage, Dordei (b. 1842), Mari (1843) and Søren Hansen (1850)",["c1865ih"]],["1900","Retired farmer's wife (føderaadskone) at Indre Hatlem, aged 88",["c1900ih"]],["1905","Died 1 March at Hatlem, a widow aged 92",["d1905t"]]],note:"Halfri's mother, and probably also Hans Hanssen sen.'s mother."},
