 hansS98:{n:"Hans Smelden (b. 1898)",st:"doc",line:"hatlem",par:["hansGS"],role:"First cousin of grandfather Harald (son of Hans Gerhard Smilden)",b:"28 Oct 1898, North Dakota",d:"July 1985",ev:[["1900","Hans, born October 1898, with his parents in Moraine township, Grand Forks Co. (US census as transcribed on the forum)",["nhs"]],["1920","Aged 21, at home in Hegton township",["nhs"]],["c. 1930","Married Veronica Caron (b. 13 Jan 1906, d. May 1979). Their children's Social Security records name the parents as Hans Smelden and Veronica Caron; the children were born at Emerado and Larimore, N.D., from 1930 on",["sbnsm"]],["1985","Died in July. The Death Master File gives his birth date as 28 Oct 1898, matching the 1900 census. He used the spelling Smelden",["sbnsm"]]]},
 thomasS:{n:"Thomas M. Smilden",st:"doc",line:"hatlem",par:["hansGS"],role:"First cousin of grandfather Harald (son of Hans Gerhard Smilden)",b:"7 Nov 1902, Moraine township, North Dakota",d:"19 Jun 1993",ev:[["1910","Aged 7, with the family in Larimore",["nhs"]],["1920","Aged 17, at home in Hegton township",["nhs"]],["1942","Served in the US Army from 12 October 1942 to 3 April 1943",["sbns"]],["1976","The county history says he and his brother Henry still lived on the family farm in Hegton township",["nhs"]],["1993","Died 19 June, living near Larimore (ZIP 58251). His Social Security record names his parents as Hans Smilden and Maren Totland",["sbns"]]]},
 henryS:{n:"Henry Smilden",st:"doc",line:"hatlem",par:["hansGS"],role:"First cousin of grandfather Harald (son of Hans Gerhard Smilden)",b:"16 Nov 1908, North Dakota",d:"26 Apr 1995",ev:[["1910","Aged 1, with the family in Larimore",["nhs"]],["1920","Aged 11, at home in Hegton township",["nhs"]],["1995","Died 26 April, living near Larimore (the same ZIP code as his brother Thomas)",["sbns"]]],note:"The Social Security entry gives no parents. He is identified by name, birth year and residence, together with the county history's statement that Tom and Henry farmed the family land."},
 ingvoldS:{n:"Ingvold Andreas Smilden",st:"prob",line:"hatlem",par:["hansGS"],role:"First cousin of grandfather Harald (son of Hans Gerhard Smilden)",b:"c. 1910, North Dakota",d:"1962",ev:[["1920","Aged 9, at home in Hegton township",["nhs"]],["1930s","Married Julia Holweger. Social Security records of their children, born from 1935 on in Grand Forks and Northwood, N.D., name the parents as Ingvold Smilden and Julia Holweger",["sbns"]],["1962","Died, according to the family-submitted Grand Forks County history (1976). A child of his sister Inga recalled on the forum that he died of a heart attack in his fifties",["nhs"]]]},
 marenT:{n:"Maren Serine Smilden (née Totland)",st:"doc",line:"hatlem",role:"Wife of Hans Gerhard Smilden",b:"Feb 1879, Moster (Finnås), Sunnhordland",d:"6 Nov 1946, Larimore, North Dakota (buried 11 Nov)",ev:[["1895","Emigrated from Bergen on 9 May, aged 16 (indexed as 'Maren Størnisdtr Totland')",["nhs"]],["1897","Married Hans Gerhard Smilden",["nhs"]],["1946","Died 6 November at Larimore of acute myocarditis, a widow, after 51 years in the US (death certificate as transcribed by a descendant). The county history gives 1948, which is probably a mistake",["nhs"]]],note:"Daughter of Gustavus Larsen Totland and Pernille Torkelsdatter. Four of her brothers and her sister emigrated before her (1882–1890): Torkel 'Tom', Laurits 'Lewis', Helge Johan 'Henry John' (d. 1943, Becker Co., MN) and Lars Andreas 'Andrew L.' (d. 1962, Hennepin Co., MN), plus Gustava. Several of them farmed at Mekinock, near Larimore, before moving to Minnesota."},
 hansJen:{n:"Hans Jensen Smilden",st:"doc",line:"hatlem",par:["jensL","ingeborgS"],role:"2nd great-grandfather",b:"c. 1832, Hyllestad",ev:[["1865","Farmer and owner (selveier) at Smilden, Hyllestad, aged 34, with his wife Halfri",["c1865s"]],["1868","Father of Ingeborg",["b1868i"]],["1875","Head of the household at Smilden",["c1875s"]],["1892","Widowed",["d1892h"]],["1893","Another farmer at Smilden, Hans Andersen (b. 1845 at Skor, son of the lodger Anders Hansen Stigestand), married Dorthea Monsdatter Dyrdal on 16 May. He was not Halfri's second husband (she had died in January 1892) and no family link to Hans Jensen has been found. A researcher's death date of 9 May 1893 for Hans Jensen is contradicted by the two 1894 weddings below (April and June), where he is named as the bride's father",["m1893ha"]],["1894","Named as the bride's father when Ingeborg married",["m1894"]],["1894","Named again as the bride's father on 8 June, when Thorine Jensine Hansdatter Smilden (b. 1871 at Smilden) married Gabriel Bertelsen Skor",["m1894tj"]]]},
