 larsP:{n:"Lars (Didrik) Pedersen",st:"prob",line:"olsen",par:["pederL","emilie"],role:"Great-grandfather (probable)",b:"7 May 1865, Malangen",d:"13 Aug 1917, Skutvik, Malangen",ev:[["1891","Lars Didrik, aged 26, at home with his parents Peder Karl Johan Larsen and Emilie Johanna Jensdatter",["c1891ml"]],["1900","Married lodger (inderst) and farm worker in his father's household at Skutvik yttre, with his wife Eline Jakobsdatter",["c1900ml"]],["1910","Farmer at Skutvik, Malangen, with his wife Eline and children Olav, Ingeborg (b. 30 Aug 1902), Emma, Lovise and a baby son. His elderly parents Peder Larsen and Emelie live with them",["c1910m"]],["1917","Died 13 August at Skutvik, a married farmer; buried 18 August at Malangen church. The burial record gives the same birth date, 7 May 1865",["bur17lp"]]],note:"Ingeborg's birth year, birthplace and maiden name (Pedersen) all match this family. No record has yet been found that names her parents directly, so the link is probable."},
 eline:{n:"Eline Hansine Pedersen (née Jakobsdatter)",st:"prob",line:"olsen",par:["jakobR","ingeborgT"],role:"Great-grandmother (probable)",b:"25 Aug 1870, Helgøy",ev:[["1891","Eline Hansine, aged 20, at home at Helgøy with her parents Jakob Edvard Rasmusen and Ingeborg Thorstensdatter",["c1891he"]],["1900","Recorded as Eline Jakobsdatter, born 1870 at Helgøy, daughter-in-law in the household of Peder Larsen at Skutvik yttre",["c1900ml"]],["1910","Wife at Skutvik, Malangen",["c1910m"]],["1920","Widow and head of the household at Skutvik ytre, with Ingeborg, Lovise and Peder Karl",["c1920m2"]],["1944","Possibly the widow Eline Hansine Pedersen of Malangen who died on 7 February 1944. That register gives her birth as 25 September 1871, not 25 August 1870, so this match is not confirmed",["d44ep"]]]},
 paulO:{n:"Paul Olsen Nøttveit",st:"doc",line:"henne",par:["oleM","kariJ"],role:"2nd great-grandfather",b:"c. 1842–1845, Fana",ev:[["1875","Farmer and owner at Nødtvedt (Nøttveit), Fana, with his wife Kari Olsdatter, children Anne Johanne, Ole and Kari, and his parents",["c1875n"]],["1891","Widower and head of the household at Nødtvedt, with his children Ole, Johannes, Johanne, Kari and Marte (b. 1877)",["c1891n"]],["1897","Named as the bride's father when Marta married",["m1897"]]],note:"Marta's father was named Paul, and she used the farm name Nøttveit. The 1891 census lists a Marte Paulsdr, born 1877, as his daughter."},
