 hansG:{n:"Hans Hansen Gjelseth",st:"doc",line:"olsen",role:"3rd great-grandfather",note:"Of Bolsøy, near Molde. Named as the bride's father in 1861.",ev:[["1861","Named as Karen's father",["m1861"]]]},
 harald:{n:"Harald Ingolf Hatlem",docs:[["img/harald-declaration-1928.jpg","US Declaration of Intention, Chicago, 12 May 1928. Source: FamilySearch, found by Gaute"]],st:"fam",line:"hatlem",par:["hansj","ingeborgH"],role:"Maternal grandfather",b:"11 Jul 1904, Hatlem, Hyllestad",d:"9 Oct 1977, Bergen",note:"Origins: Family lore places an English origin on Gaute's mother's side. No English link has been found in any line. A scan of the Hyllestad censuses of 1865, 1875 and 1900 and the Fana censuses of 1875 and 1900 found no British-born person in any of the family's households. The few British-born people in Fana in 1900 were glassworks families and a consul's housekeeper, none of them related. The scan found no evidence for or against the story.",ev:[["1904","Born 11 July at Hatlem, Hyllestad",["hh1910"]],["1910","With his family at Tørklep øvre, Våle (Vestfold)",["hh1910"]],["1920","Apprentice typographer, Valberg, Nesttun (Fana)",["hh1920"]],["1925","Registered on 13 July with the Bergen police to emigrate. Unmarried, a typographer from Nesttun, travelling on the Cunard Line with a passport, on a ticket sent from America. The destination given was Minneapolis, Minnesota",["em1925"]],["1925","Left England on 18 July, recorded as Harold Hatlem, born 1904, on the UK outgoing passenger list",["uk1925"]],["1925","Arrived in New York on the Aquitania on 24 July",["di1928"]],["1928","Filed a Declaration of Intention to become a US citizen at the US District Court in Chicago on 12 May. He is named as Harold Hatlem, a 23-year-old printer living at 915 E. 42nd Place, Chicago. He was unmarried, with a fair complexion, blond hair and blue eyes, 5 ft 6 in and 140 lb, and signed as Harold H. Hatlem. So by 1928 he lived in Chicago, not Minneapolis",["di1928"]],["after 1928","Returned to Norway (confirmed by family). The return date is unknown"],["1944","Married Klara Cecilie Henneli on 5 May (Birkeland, Fana)",["m1944","m1944c"]],["1977","Died 9 October in Bergen"]]},
