 hansj:{n:"Hans Hansen Hatlem",docs:[["img/hans-stalbans-1912.jpg","St. Albans border index card, Ascania via Quebec, September 1912. Source: FamilySearch (NARA M1461), image supplied by Gaute"]],st:"fam",line:"hatlem",par:["hanss","petrine"],role:"Great-grandfather",b:"31 May 1868, Hyllestad",d:"1954, Fana",ev:[["1890","Registered on 29 May with the Bergen police to emigrate, as Hans Hansen Hatlem, born 1868, Hyllestad, unmarried farmer's son. Very likely him, since the name, year and parish all match",["em1890"]],["1894","Married Ingeborg Hansdatter Smilden on 5 April. Born at Varlien; his father is Hans Hansen Vartien Hathlem",["m1894"]],["1890","Arrived in New York on the Gallia on 13 June as Hans H. Hatlem, aged 21, from Norway; Gaute has confirmed the full name on the FamilySearch record. The manifest line (NARA M237, roll 550) reads 'Hans H. Hatlem, 21'; the destination is hard to read but appears to be Wisconsin, as earlier transcribed",["gal1890","fh"]],["1890","Lived in the US 1890–1892 at Marinette, Wisconsin, according to his own statement on his 1912 border card",["card12"]],["1912","Registered on 22 August to emigrate to North Dakota with his son Hjalmar (b. 1898). He was a married farmer living at Myrdal, Fana",["em1912"]],["1912","Crossed from Canada into the US through the St. Albans, Vermont district. His border index card shows he sailed on the Ascania to Quebec (card dated 9-6-12, i.e. 6 September 1912, US-style), with his son Hjalmar, 15. It gives him as born in Hyllestad, aged 43, married, a farmer, able to read; last residence Nesttun, Norway; nearest relative his wife Ingeborg Hatlem near Bergen. He had been in the US before, 1890–1892, at Marinette, Wisconsin, paid his own passage, and carried $25. His destination was Larimore, North Dakota, to his brother-in-law Hans H. Smelden (Hans Gerhard Smilden). Height 5 ft 7 in, blue eyes",["card12","sta12h","fh"]],["1875","Aged 7, with his parents Hans Hanssen and Petrine Andersdatter at Varlien, Hyllestad",["c1875h"]],["1900","Farmer and owner of Ytre Hatlem (gnr. 27, bnr. 7), with his wife Ingeborg, their children and his retired parents",["c1900h"]],["1910","At Tørklep øvre, Våle, Vestfold",["hh1910"]],["1920","Building carpenter, Valberg, Nesttun (Fana)",["hh1920"]],["1954","Died in Fana",["dh1954"]]]},
 ingeborgH:{n:"Ingeborg Hatlem (née Hansdatter)",st:"fam",line:"hatlem",par:["hansJen","halfri"],role:"Great-grandmother",b:"26 Aug 1868, Hyllestad",d:"1954, Fana",ev:[["1868","Baptised 13 September at Øn church, Hyllestad, daughter of Hans Jensen and Halfri Hansdatter of Smilden",["b1868i","b1868i2"]],["1875","Aged 8, with her parents at Smilden",["c1875s"]],["1894","Married Hans Hansen Hathlem on 5 April. She is recorded as Ingeborg Hansdtr Smilden, born 1868 at Smilden, and her father as Hans Jensen Smilden",["m1894"]],["1900","Farmer's wife at Ytre Hatlem",["c1900h"]],["1920","Valberg, Nesttun",["hh1920"]],["1954","Died in Fana",["di1954"]]],note:"Her parents are documented in her baptism and marriage records."},
 hanss:{n:"Hans Hanssen Hatlem (sen.)",st:"doc",line:"hatlem",par:["hansJH","trineK"],role:"Great-great-grandfather",b:"1838, Hatlem, Øn parish, Hyllestad",d:"24 Apr 1903 (buried 4 May)",note:"Probably the Hans born 16 Oct 1838 at Hatlem to Hans Jensen and Trine Clausdatter, which would make him a brother of Halfri, his son's mother-in-law. See Hans Jensen (Hatlem).",ev:[["1881","Probably the father of Martin, born 18 November and died 17 December. The next of kin was Hans Hansen Varlien",["b1881m"]],["1903","Died 24 April; buried 4 May",["d1903h"]],["1875","Farmer (selveier), Varlien, Hyllestad, with Petrine and sons Hans, Anders and Andreas",["c1875h"]],["1891","Head of the household at Hatlem with Petrine and children Andreas, Thrine Andrine and Anna Marie",["c1891h"]],["1900","Retired (føderaadsmand) at Ytre Hatlem, living with his son Hans",["c1900h"]],["1903","Buried 4 May, Øn",["dh1903"]]],note:"His parents have not been found yet."},
 petrine:{n:"Petrine Andersdatter",st:"doc",line:"hatlem",role:"Great-great-grandmother",b:"28 Jul 1842, Hyllestad",d:"2 Apr 1937, Hyllestad",ev:[["1865","Unmarried servant (tjenestepige), aged 24, at Ytre Hatlem in the household of Anders Johannesen",["c1865p"]],["1884","Mother of a child baptised in Hyllestad, living at Varlien",["b1884am"]],["1937","Died 2 April, a widow in Hyllestad, aged 94",["d1937p"]],["1865","Unmarried servant at Ytre Hatlem",["c1865h"]],["1875","Wife of Hans Hanssen, Varlien",["c1875h"]],["1910","Widow, retired, Hatlem ytre",["c1910h"]],["1920","Widow, Hatlem ytre",["c1920h"]]],note:"Her parents are documented in her baptism and marriage records."},
 lars:{n:"Lars Larsen Hennelien",st:"fam",line:"henne",par:["larsJ","caecilie"],role:"Great-grandfather",b:"6 Aug 1871, Fana",ev:[["1891","Probably the Lars Larsen Kalland, born 1871, living at Kalland as the stepson of Amund Eliasen, whose wife was Cesilia Larsdatter",["c1891k"]],["1897","Married Marta Paulsdatter on 8 November in Fana. He is recorded as Lars Larssen Smøraas, born 1871 at Smøraas and living in Laksevåg, son of Lars Johannessen Smøraas. Her father is Paul Olsen Nødtvedt",["m1897"]],["1900","At Myrdal, Hamre, with his wife Martha and sons",["c1900f"]],["1910","Farmer at Henne, Fana (gnr. 60, bnr. 2), with nine in the household",["c1910f"]],["1914","Father of Klara Cecilie",["bk1914"]],["1920","Farmer, Henne",["c1920f"]],["1930","Named as the groom's father at the wedding of his son Johannes on 19 June, so very probably still alive then",["m1930jh"]]],note:"His death has not been found yet. He is last seen alive in June 1930, at his son Johannes's wedding."},
 marta:{n:"Marta Paulsdatter Nøttveit",st:"fam",line:"henne",par:["paulO","kariO"],role:"Great-grandmother",b:"20 Feb 1877, Fana",d:"25 Sep 1963, Fana",ev:[["1897","Married Lars Larssen Smøraas on 8 November. She is recorded as born 1877 at Nødtvedt, daughter of Paul Olsen Nødtvedt",["m1897"]],["1891","Marte Paulsdr, aged 14, at Nødtvedt, Fana, in the household of her widowed father Paul Olsen Nødtvedt",["c1891n"]],["1900","Myrdal, Hamre",["c1900f"]],["1910","Farmer's wife at Henne",["c1910f"]],["1920","Housewife at Henne. This census gives her farm name, Nøttveit",["c1920m"]],["1963","Died 25 September in Fana, registered as Marta Henne",["dmh63"]]],note:"Her father was named Paul, according to her patronymic. Her parents have not been found yet."},
