for(const p of Object.values(P))if(p.ev){const y=e=>{const m=String(e[0]).match(/\d{4}/);return m?+m[0]:9999};p.ev=p.ev.map((e,i)=>[e,i]).sort((a,b)=>y(a[0])-y(b[0])||a[1]-b[1]).map(x=>x[0])}
